package com.github.tartaricacid.touhoulittlemaid.world;
import com.github.tartaricacid.touhoulittlemaid.entity.passive.EntityMaid;import net.minecraft.nbt.NBTTagCompound;import net.minecraft.server.MinecraftServer;import net.minecraft.world.WorldServer;import java.util.UUID;
/** Cross-dimension duplicate guard for every serialized maid restoration path. */
public final class MaidWorldIndex{private MaidWorldIndex(){}public static UUID uuid(NBTTagCompound tag){return tag!=null&&tag.hasKey("UUIDMost")&&tag.hasKey("UUIDLeast")?new UUID(tag.getLong("UUIDMost"),tag.getLong("UUIDLeast")):null;}public static EntityMaid findLoaded(UUID id){if(id==null||MinecraftServer.getServer()==null)return null;WorldServer[] worlds=MinecraftServer.getServer().worldServers;if(worlds==null)return null;for(WorldServer world:worlds)if(world!=null)for(Object object:world.loadedEntityList)if(object instanceof EntityMaid&&!((EntityMaid)object).isDead&&id.equals(((EntityMaid)object).getUniqueID()))return(EntityMaid)object;return null;}public static boolean canRestore(NBTTagCompound tag){UUID id=uuid(tag);return id==null||findLoaded(id)==null;}}
